import { mc, pt, ref } from './helpers.js'

export const STAGE4 = [
{
  id: 'distributed-intro', title: 'Distributed systems: availability, reliability, fault tolerance', stage: 4, tier: 'must', minutes: 50, prereq: ['load-balancing', 'replication-sharding'], related: ['cap-consistency', 'idempotency-retries'],
  hook: { story: 'Your system now has 20 servers, 3 databases, a cache cluster and a queue. Each machine fails about once every 3 years. Sounds reliable.', ask: 'With 40 machines, how often will something be broken on any given week? Does your design assume that nothing is ever broken?', hints: ['If each machine fails once in ~150 weeks, 40 machines give how many failures per week?', 'What should happen to users while one is broken?', 'What can you not tell apart from the outside: a crashed machine, or a slow network?'], reveal: 'With 40 machines you expect a failure roughly every 4 weeks, and at larger scale, every day. In a distributed system partial failure is the normal state, so design must continue working (or degrade gracefully) while parts are broken, and must cope with the fact that a slow machine looks identical to a dead one.' },
  levels: [
    { title: 'Understand', body: ['A **distributed system** is many computers cooperating to look like one. It exists because one machine is not big enough or safe enough.', '**Availability:** is the system answering? **Reliability:** is it answering correctly and consistently over time? **Fault tolerance:** it keeps working when parts fail. **Redundancy:** having spares (extra servers, copies of data) so one failure is not fatal.', 'Availability is measured in "nines": 99.9% = ~8.8 hours of downtime a year; 99.99% = ~53 minutes; 99.999% = ~5 minutes.'],
      check: mc('Which gives the least downtime per year?', ['99%', '99.9%', '99.99%', '90%'], 2, 'More nines, less downtime.') },
    { title: 'Explore', body: ['The classic fallacies of distributed computing: the network is reliable, latency is zero, bandwidth is infinite, the network is secure, topology does not change, there is one administrator, transport cost is zero, the network is homogeneous. All false.', 'Failure types: **crash** (stops), **omission** (messages lost), **timing** (too slow), **byzantine** (wrong/malicious). Most designs assume crash and omission.'],
      steps: ['**Redundancy:** N+1 servers, replicated data, multiple zones/regions.', '**Failure detection:** heartbeats and timeouts (but you can never be sure: slow vs dead).', '**Failover:** shift work to spares automatically.', '**Graceful degradation:** drop non-essentials (recommendations) but keep the core (checkout).', '**Availability maths:** in series, multiply (0.99 × 0.99 = 0.98); in parallel, 1 - (1-a)(1-a) = 0.9999 for two 99% components.'],
      check: mc('Two independent 99% components in series have availability about…?', ['99.99%', '98%', '100%', '50%'], 1, '0.99 × 0.99 ≈ 0.98: chains reduce availability.') },
    { title: 'Apply', body: ['**Scenario: a service becomes unavailable but other services continue working.** Product pages call a recommendations service; it dies. If the product page waits 30 s and then fails, one dependency took down the page. A resilient design uses a short timeout, a fallback (popular items), and a circuit breaker, so recommendations vanish but the page loads.', 'Exercise: for each dependency in your system, ask "what does the user see when this is down?" If the answer is "an error", decide if that is acceptable.'],
      check: mc('Recommendations are down. Best behaviour for the product page?', ['Error page', 'Timeout fast and show fallback content', 'Wait forever', 'Retry 100 times'], 1, 'Degrade gracefully.') },
    { title: 'Master', body: ['Design to the **failure domain**: spread replicas across machines, racks, availability zones and regions, so a single event cannot kill all copies. Avoid **correlated failures** (same bad deploy to everything, same config push, same dependency). Use **canary/progressive rollouts**, feature flags, and **chaos testing** (Netflix Chaos Monkey) to prove fault tolerance. Define **SLIs/SLOs** (e.g. 99.9% of requests < 300 ms) and use **error budgets** to balance reliability against feature velocity.', 'Reminder: you can never perfectly detect failure over an unreliable network, which is why timeouts, retries and idempotency (next lessons) are inseparable from distributed design.'],
      check: mc('Why deploy a change to 1% of servers first?', ['Faster', 'Limit blast radius of a bad change (canary)', 'Cheaper', 'DNS'], 1, 'Correlated failure from a bad deploy is common.') },
  ],
  diagram: { caption: 'Spread across failure domains', rows: [['Users'], ['Global routing'], ['Zone A', 'Zone B', 'Zone C']], link: 'fan' },
  sections: { when: ['Whenever availability targets or scale exceed what one machine provides.'], whenNot: ['Do not distribute what one machine can do reliably; distribution adds failure modes.'], tradeoffs: ['Availability and scale vs complexity and consistency difficulty.'], real: ['AWS multi-AZ deployments, Google SRE SLOs, Netflix Chaos Engineering.'] },
  connects: 'Replication gives redundancy; the next lesson shows what you must give up to keep data copies consistent under network failures.',
  quiz: [
    mc('What is redundancy?', ['Wasteful code', 'Spare components so one failure is survivable', 'A cache', 'A protocol'], 1, 'Spares for resilience.'),
    mc('What is graceful degradation?', ['Crashing politely', 'Keeping core functions while non-essential ones fail', 'Slow code', 'Encrypted logs'], 1, 'Partial service beats none.'),
    mc('What is a failure domain?', ['A URL', 'A set of things that fail together (rack, zone, region)', 'A table', 'A cache'], 1, 'Spread replicas across domains.'),
    mc('All replicas are in one availability zone. The zone loses power. Result?', ['No impact', 'Total outage despite replication', 'Faster', 'Lower cost'], 1, 'Redundancy within one domain does not help.', 'scenario'),
    mc('A config push to all servers at once breaks them all. Prevention?', ['More servers', 'Progressive/canary rollout with automatic rollback', 'Longer TTLs', 'Bigger DB'], 1, 'Limit blast radius.', 'scenario'),
  ],
  interview: { q: 'How do you make a system highly available, and how do you measure it?', model: 'Remove single points of failure with redundancy at every tier (multiple servers behind balancers, replicated data, multi-AZ/region). Detect failures with health checks, fail over automatically, use timeouts and graceful degradation, and deploy progressively. Measure with SLIs/SLOs (availability, latency, error rate) and error budgets; compute availability of serial/parallel components. Acknowledge trade-offs with consistency and cost.', points: [pt('Eliminate single points of failure / redundancy', 'redundan', 'single point', 'spof'), pt('Failover and health checks', 'failover', 'health'), pt('Multi-AZ / multi-region', 'zone', 'region'), pt('SLO/SLI and nines', 'slo', 'sli', 'nines', '99'), pt('Graceful degradation / progressive rollout', 'degrad', 'canary', 'rollout')] },
  challenge: { q: 'Your checkout calls 5 services, each 99.9% available, in series. What is the end-to-end availability? Propose two changes that raise it without making each service better.', hints: ['0.999^5.', 'Which calls are really required for the user to pay?'], model: '0.999^5 ≈ 99.5% (about 44 hours of downtime a year). Improve by removing non-essential synchronous dependencies (make them async/optional with fallbacks) and by adding redundancy/retries with idempotency to the critical ones so they become parallel rather than serial.', points: [pt('Computes ≈99.5%', '99.5', '0.995'), pt('Makes non-essential calls async/optional', 'async', 'optional', 'fallback', 'non-essential'), pt('Adds redundancy/retry for critical calls', 'redundan', 'retry', 'replica')] },
  summary: { key: ['Failure is normal at scale.', 'Availability = nines; series multiplies, parallel improves.', 'Spread across failure domains.'], mistakes: ['Assuming the network is reliable.', 'Redundancy inside one failure domain.'], remember: 'Design for the failure, not for the happy path.' },
  refs: [ref('Google SRE Book: Embracing Risk', 'https://sre.google/sre-book/embracing-risk/', 'Availability targets and error budgets explained by Google.'), ref('AWS Well-Architected: Reliability Pillar', 'https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/welcome.html', 'Practical reliability design principles.')],
},
{
  id: 'cap-consistency', title: 'CAP theorem and consistency models', stage: 4, tier: 'must', minutes: 55, prereq: ['replication-sharding', 'distributed-intro'], related: ['dist-transactions', 'consensus-locks'],
  hook: { story: 'Two data centres hold copies of your user\'s bank balance. The cable between them is cut. A deposit arrives at data centre A. A withdrawal request arrives at data centre B a second later.', ask: 'B cannot talk to A. Should B answer using what it knows (possibly stale), or refuse until the cable is back? Which choice is right for a bank? For a "likes" counter?', hints: ['If B answers, what could it get wrong?', 'If B refuses, what happens to the user?', 'Is the cost of being wrong the same for all data?'], reveal: 'During a network partition you must choose: **consistency** (refuse/wait, so nobody sees wrong data) or **availability** (answer with possibly stale data). The right choice depends on the cost of being wrong, which differs between a bank balance and a like counter.' },
  levels: [
    { title: 'Understand', body: ['When data is copied to several machines, they can briefly disagree. **Consistency** means everyone sees the same, latest data. **Availability** means every request gets an answer.', 'The **CAP theorem** says: when the network **P**artitions (machines cannot talk), a system can keep only one of **C**onsistency or **A**vailability. You cannot have both during the split.', 'Partitions are not optional in real networks, so the real choice is C or A **when things go wrong**.'],
      check: mc('During a network partition CAP says you must choose between…?', ['Speed and cost', 'Consistency and availability', 'Latency and bandwidth', 'SQL and NoSQL'], 1, 'C or A when P happens.') },
    { title: 'Explore', body: ['**CP systems** refuse or error rather than return stale data (e.g. ZooKeeper, etcd, HBase, Spanner-style systems). **AP systems** keep answering and reconcile later (e.g. Cassandra and DynamoDB by default). Many are tunable.', '**PACELC** refines CAP: if there is a Partition, choose A or C; **E**lse (normal operation), choose between **L**atency and **C**onsistency. Even without failures, stronger consistency costs coordination time.'],
      steps: ['**Strong (linearizable) consistency:** behaves like one copy; every read sees the latest write. Slowest; needs coordination.', '**Sequential/causal consistency:** operations respect order or cause-and-effect (a reply never appears before its question).', '**Read-your-writes / monotonic reads:** session guarantees; cheap and often enough.', '**Eventual consistency:** if writes stop, all copies converge. Fast and available; users may briefly see stale data.', '**Quorums:** with N replicas, write to W and read from R; if R + W > N, a read overlaps the latest write.'],
      check: mc('N=3, W=2, R=2. Do reads see the latest write?', ['No', 'Yes, because R + W > N so read and write sets overlap', 'Only if N=1', 'Only with caching'], 1, '2 + 2 > 3.') },
    { title: 'Apply', body: ['**Scenario: choose per feature.** Bank transfer/inventory of the last ticket: strong consistency (CP), accept errors during partitions. Social feed, like counts, view counts: eventual (AP), stale is fine. Shopping cart: Amazon\'s Dynamo chose availability, merging carts on conflict (never lose an add-to-cart). User profile: read-your-writes.', 'Interview move: never say "we will use eventual consistency" generally. Say which data, why staleness is acceptable, how long it lasts, and how conflicts are resolved.'],
      check: mc('Which data most needs strong consistency?', ['Like counts', 'Remaining seats for a concert', 'Profile photo', 'Trending list'], 1, 'Overselling is costly.') },
    { title: 'Master', body: ['Conflict resolution under AP: **last-write-wins** (simple, loses data, clock-skew risk), **vector clocks** (detect concurrent writes), **CRDTs** (data types that merge deterministically: counters, sets), application-level merge. **Clock caveats:** physical clocks drift; logical/hybrid clocks order events; Google Spanner uses TrueTime (bounded uncertainty) to offer external consistency globally at a latency cost.', 'CAP is often misquoted: it is about partitions only, about one specific definition of consistency (linearizability), and a system can choose different trade-offs for different operations.'],
      check: mc('Why is last-write-wins dangerous?', ['It is slow', 'Concurrent updates can silently overwrite each other, especially with skewed clocks', 'It needs a quorum', 'It uses too much memory'], 1, 'Data can be lost without errors.') },
  ],
  diagram: { caption: 'Partition: pick C or A', rows: [['Client'], ['Node A (has deposit)', 'Node B (cannot reach A)'], ['CP: refuse', 'AP: answer stale']], link: 'chain' },
  sections: { when: ['CP for money, inventory, locks, leader election. AP for feeds, counters, carts, caches.'], whenNot: ['Do not use eventual consistency where wrong answers cause irreversible harm.'], tradeoffs: ['Correctness vs uptime/latency.'], real: ['Amazon Dynamo (AP), Google Spanner (CP with TrueTime), Cassandra tunable consistency.'] },
  connects: 'This explains the replica-lag problem from the previous lesson as a deliberate consistency choice, and prepares you for transactions that span services.',
  quiz: [
    mc('What does eventual consistency guarantee?', ['Immediate agreement', 'Copies converge if updates stop', 'No failures', 'Fast writes only'], 1, 'Convergence over time.'),
    mc('PACELC adds what idea?', ['Cost', 'Even without partitions, latency vs consistency trade-off', 'Security', 'Memory'], 1, 'The "else" clause.'),
    mc('Which can merge concurrent updates without conflicts?', ['A CRDT counter', 'A plain integer with LWW', 'A local variable', 'A cookie'], 0, 'CRDTs are designed to merge deterministically.'),
    mc('A global like-counter must stay available worldwide even during a partition. Choose?', ['Strong consistency', 'Eventual consistency with mergeable counters', 'Single node', 'Drop likes'], 1, 'Accept brief divergence.', 'scenario'),
    mc('Two users book the same seat simultaneously in different regions. Required guarantee?', ['Eventual', 'Strong consistency / single-writer for that seat', 'None', 'Cache'], 1, 'Needs coordination.', 'scenario'),
  ],
  interview: { q: 'Explain the CAP theorem and give examples of systems and use-cases for each side.', model: 'CAP: during a network partition a replicated system must choose consistency (all clients see the same latest data, so some requests fail or block) or availability (every request gets a response, maybe stale). Partitions are inevitable so the choice is C vs A under failure. CP examples: etcd/ZooKeeper, Spanner, bank ledgers. AP examples: Dynamo, Cassandra, shopping carts, feeds. Add PACELC: even normally there is a latency vs consistency trade-off. Choose per feature by the cost of stale data, and explain conflict resolution (LWW, vector clocks, CRDTs).', points: [pt('Definition: partition forces C vs A', 'partition'), pt('Examples CP and AP', 'cassandra', 'dynamo', 'zookeeper', 'etcd', 'spanner'), pt('Chooses by use case/cost of staleness', 'bank', 'like', 'inventory', 'use case'), pt('PACELC / latency trade-off', 'pacelc', 'latency'), pt('Conflict resolution', 'last-write', 'vector', 'crdt', 'conflict')] },
  challenge: { q: 'Pick a consistency model for each: (1) bank balance, (2) tweet like count, (3) a user\'s own profile edit, (4) a collaborative document. Justify each in one line.', hints: ['What is the cost of a stale read?', 'Whose view needs to be fresh?'], model: '(1) Strong: wrong balance is harmful. (2) Eventual: approximate counts are fine. (3) Read-your-writes: the author must see their edit; others can lag. (4) Causal/convergent via OT or CRDTs so concurrent edits merge without losing work.', points: [pt('Balance strong', 'strong', 'linearizab'), pt('Counts eventual', 'eventual'), pt('Profile read-your-writes', 'read-your-writes', 'own'), pt('Docs CRDT/OT/causal', 'crdt', 'ot', 'causal', 'merge')] },
  summary: { key: ['CAP: C or A during a partition.', 'PACELC: else latency vs consistency.', 'Choose consistency per feature.'], mistakes: ['"We are AP so we are fast" (ignoring correctness).', 'Treating CAP as a three-way pick.'], remember: 'Ask: what is the cost of a stale or wrong answer?' },
  refs: [ref('Amazon Dynamo paper (Werner Vogels)', 'https://www.allthingsdistributed.com/2007/10/amazons_dynamo.html', 'Landmark AP design and the shopping-cart example.'), ref('Jepsen: Consistency Models', 'https://jepsen.io/consistency', 'The clearest map of consistency models.'), ref('Martin Kleppmann: Designing Data-Intensive Applications', 'https://dataintensive.net/', 'The book that explains replication and consistency best (read chapters 5 and 9).')],
},
{
  id: 'idempotency-retries', title: 'Idempotency, retries and circuit breakers', stage: 4, tier: 'must', minutes: 50, prereq: ['queues', 'http-rest', 'distributed-intro'], related: ['dist-transactions'],
  hook: { story: 'The payment service charges the card successfully, then the network drops before the reply reaches your server. Your server sees a timeout.', ask: 'Do you retry? If you do, the customer may be charged twice. If you do not, you may lose the sale. What do you do?', hints: ['From your side, can you tell "failed" from "succeeded but reply lost"?', 'What property would make a retry harmless?', 'What if the payment service is struggling and everyone retries?'], reveal: 'You cannot tell, so retries must be made safe: operations should be **idempotent** (doing them twice has the same effect as once) using an idempotency key. And retries must be controlled (backoff, limits, circuit breakers) so they do not worsen an outage.' },
  levels: [
    { title: 'Understand', body: ['**Idempotent** means "safe to repeat". Pressing an elevator button five times is the same as pressing it once. "Set balance to 100" is idempotent; "add 100 to balance" is not.', 'Networks lose messages and replies, so callers retry. A retry is only safe if the operation is idempotent.', 'A **circuit breaker** works like an electrical fuse: after repeated failures it "opens" and stops sending requests to a broken service for a while, failing fast instead of piling up.'],
      check: mc('Which operation is idempotent?', ['Add ₹100 to balance', 'Set status = "shipped"', 'Append a log line', 'Create a new order'], 1, 'Setting an absolute value is repeatable.') },
    { title: 'Explore', body: ['**Idempotency key pattern:** the client generates a unique key per logical action and sends it with every attempt. The server stores `key -> result`; a repeat returns the stored result without re-doing the work.'], code: { lang: 'python', text: 'def charge(key, user, amount):\n    prior = store.get(key)\n    if prior: return prior                 # replay safely\n    with db.transaction():\n        if not db.insert_if_absent("idem", key):   # unique constraint closes the race\n            return store.wait_for(key)\n        result = payments.charge(user, amount)\n        db.save_result(key, result)\n    return result' },
      steps: ['**Retry with exponential backoff + jitter:** wait 100 ms, 200, 400… plus random jitter so clients do not synchronise.', '**Retry budget:** cap retries (e.g. 3) and only retry safe/idempotent errors (timeouts, 503), not 400s.', '**Timeouts:** every call needs one, shorter than the caller\'s own timeout.', '**Circuit breaker states:** closed (normal) → open (fail fast after N failures) → half-open (let a trial request through) → closed.', '**Bulkheads:** separate resource pools so one slow dependency cannot use all threads.'],
      check: mc('Why add jitter to backoff?', ['To slow things down', 'So many clients do not all retry at the same instants', 'To encrypt', 'To save logs'], 1, 'Avoid synchronised retry waves.') },
    { title: 'Apply', body: ['**Scenario: users are receiving duplicate notifications.** Trace: the queue redelivered a message after a worker timeout, and the worker is not idempotent. Fix: key each notification (`event_id + channel`), record it in a table with a unique constraint **before** sending, and skip if it exists. For payments use the provider\'s idempotency key.', '**Scenario: a downstream service is down.** With 3 retries per layer across 3 layers, one user request can become 27 calls: **retry amplification**. Retry at one layer only, and use a circuit breaker so the failing service gets breathing room.'],
      check: mc('Three layers each retry 3 times. One failing call can become…?', ['3', '9', '27', '1'], 2, 'Multiplicative amplification.') },
    { title: 'Master', body: ['Exactly-once is built from at-least-once + idempotency (dedupe by key within a retention window). Keys must live long enough to cover the longest retry horizon, and the dedupe check and the side effect must be **atomic** (unique constraint or transaction), or a race between two concurrent duplicates still double-charges. Not all effects can be undone or deduped (sending an email through a provider with no idempotency support): use an outbox and accept rare duplicates, or record intent first. Also: **hedged requests** (send a second request if the first is slow) cut tail latency at the price of extra load; apply only to idempotent reads.'],
      check: mc('Two identical requests arrive at the same instant. What makes dedupe safe?', ['Hoping', 'An atomic insert with a unique constraint on the key', 'A longer timeout', 'A cache with TTL only'], 1, 'Check-then-act without atomicity races.') },
  ],
  diagram: { caption: 'Retry with an idempotency key', seq: [['Client', 'Server', 'charge(key=K1, ₹500)'], ['Server', 'Client', '(reply lost)'], ['Client', 'Server', 'retry charge(key=K1)'], ['Server', 'Client', 'stored result for K1 (no second charge)']] },
  sections: { when: ['Every call that crosses a network and has side effects: payments, orders, notifications, webhooks.'], whenNot: ['Do not blindly retry non-idempotent operations or client errors (4xx).'], tradeoffs: ['Safety needs storage and design effort; retries add resilience but also load.'], real: ['Stripe idempotency keys; AWS SDK retries with backoff and jitter; Netflix Hystrix (circuit breakers) and Resilience4j.'] },
  connects: 'Queues give at-least-once delivery; this lesson is the other half that makes it correct. It also sets up sagas, which rely on idempotent steps and compensations.',
  quiz: [
    mc('What does a circuit breaker do when the downstream is failing?', ['Retries faster', 'Stops calls for a while and fails fast', 'Encrypts', 'Deletes data'], 1, 'Gives the dependency time to recover.'),
    mc('Which errors are generally safe to retry?', ['400 Bad Request', 'Timeouts and 503 on idempotent calls', '404', '403'], 1, 'Transient failures only.'),
    mc('What is retry amplification?', ['Faster retries', 'Retries at multiple layers multiplying load', 'A cache', 'DNS'], 1, 'Nested retries multiply.'),
    mc('A webhook receiver gets the same event twice. What should it do?', ['Process both', 'Dedupe by event id and process once', 'Crash', 'Ignore all'], 1, 'Senders retry; receivers dedupe.', 'scenario'),
    mc('A service is slowly failing. All clients retry instantly. What happens?', ['Recovery', 'Overload gets worse (retry storm)', 'Nothing', 'Cheaper'], 1, 'Retries add load at the worst moment.', 'scenario'),
  ],
  interview: { q: 'A payment request times out. How do you ensure the customer is charged exactly once?', model: 'We cannot know whether the charge happened, so we make retries safe. The client generates an idempotency key per payment attempt and sends it each time; the payment service stores key -> result atomically (unique constraint) and returns the stored result for repeats. Use timeouts, exponential backoff with jitter and a retry cap, a circuit breaker for outages, and reconcile via the provider\'s webhook or a status query. Persist intent before calling and reconcile asynchronously for unknown outcomes.', points: [pt('Cannot distinguish failure from lost reply', 'cannot tell', 'unknown', 'lost'), pt('Idempotency key stored with result', 'idempotency key', 'key'), pt('Atomic dedupe (unique constraint)', 'unique', 'atomic'), pt('Backoff + jitter + cap', 'backoff', 'jitter'), pt('Reconciliation / status check / circuit breaker', 'reconcil', 'webhook', 'status', 'circuit')] },
  challenge: { q: 'Make "send password-reset email" safe against duplicate queue deliveries and provider timeouts. Describe the data you store and the steps.', hints: ['What is the unique identity of this email?', 'What if the provider succeeded but timed out?'], model: 'Key = reset_request_id. Table sent_emails(key UNIQUE, status). Worker: insert key as "sending" (unique constraint; if it exists and is "sent", skip); call provider with the key as its idempotency/dedupe id; on success mark "sent". On timeout, retry with the same key so the provider dedupes; if unsupported, accept a rare duplicate for this low-harm case.', points: [pt('Unique key for the logical email', 'unique', 'key', 'request id'), pt('Record state before/after sending', 'status', 'sending', 'sent', 'record'), pt('Same key on retry', 'same key', 'retry'), pt('Acknowledges residual duplicate risk', 'rare', 'residual', 'accept', 'low-harm')] },
  summary: { key: ['Idempotent = safe to repeat.', 'Idempotency keys + atomic dedupe.', 'Retry with backoff, jitter, caps; use circuit breakers.'], mistakes: ['Retrying everywhere.', 'Check-then-act without atomicity.'], remember: 'Assume every message can be delivered twice and every reply can be lost.' },
  refs: [ref('Stripe: Idempotent requests', 'https://docs.stripe.com/api/idempotent_requests', 'How a real payment API implements idempotency keys.'), ref('AWS Builders\' Library: Timeouts, retries and backoff with jitter', 'https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/', 'Excellent practical guide from Amazon engineers.'), ref('Martin Fowler: Circuit Breaker', 'https://martinfowler.com/bliki/CircuitBreaker.html', 'Short, clear explanation of the pattern.')],
},
{
  id: 'dist-transactions', title: 'Distributed transactions: 2PC and sagas', stage: 4, tier: 'advanced', minutes: 55, prereq: ['transactions-acid', 'idempotency-retries', 'cap-consistency'], related: ['event-driven-obs', 'consensus-locks'],
  hook: { story: 'Placing an order now involves three services, each with its own database: Orders, Payments and Inventory. Payment succeeds, inventory reservation fails.', ask: 'There is no single database transaction spanning all three. How do you avoid charging the customer for something you cannot ship?', hints: ['Could you make all three agree before any of them commits?', 'What if one of them crashes during that agreement?', 'Could you instead undo the payment afterwards?'], reveal: 'Two families of answers: **two-phase commit** (coordinate so all commit or all abort: strong, but blocking and fragile) or a **saga** (a sequence of local transactions with compensating actions that undo earlier steps if a later one fails: available and scalable, but only eventually consistent).' },
  levels: [
    { title: 'Understand', body: ['Inside one database a transaction is all-or-nothing. When one business action touches **several services or databases**, there is no built-in "all or nothing". You must build it.', '**Two-phase commit (2PC):** a coordinator asks everyone "can you commit?" (prepare). If all say yes, it says "commit" to all. If anyone says no, "abort" to all.', '**Saga:** do the steps one after another, each in its own local transaction. If step 3 fails, run **compensating** actions for steps 2 and 1 (refund the payment, release the stock).'],
      check: mc('In a saga, what does a compensating action do?', ['Speeds up the transaction', 'Semantically undoes a previously completed step', 'Locks the tables', 'Encrypts data'], 1, 'E.g. refund after a failed shipment.') },
    { title: 'Explore', body: ['**2PC details:** Phase 1 participants lock resources and vote; Phase 2 the coordinator decides. Problem: if the coordinator crashes after prepare, participants stay locked and **blocked** until it returns. It is slow (several round trips, locks held) and hurts availability.', '**Saga styles:** **orchestration** (a central orchestrator tells each service what to do next and handles failures; easy to follow) vs **choreography** (services react to each other\'s events; loosely coupled but harder to trace).'],
      steps: ['Order created (PENDING)', 'Reserve inventory (compensate: release)', 'Charge payment (compensate: refund)', 'Confirm order (COMPLETED) or mark CANCELLED if any step failed', 'Every step and every compensation must be **idempotent** and retried until it succeeds.'],
      check: mc('Biggest weakness of 2PC in a service architecture?', ['Too simple', 'Blocking locks and a coordinator that is a single point of failure', 'It is eventually consistent', 'No ordering'], 1, 'Hurts availability and throughput.') },
    { title: 'Apply', body: ['**Scenario:** payment succeeded but inventory failed. Saga: orchestrator calls refund (compensation); if refund times out it retries with the same idempotency key; the order ends as CANCELLED and the customer is notified. During the saga the order is visibly PENDING: sagas lack isolation, so other readers can see intermediate states. Design the UI/data for that (e.g. "reserved" stock, "pending" orders).', 'Design question: can a step be compensated at all? Sending an email cannot be unsent. Order steps so non-compensable ones come **last** (the "pivot" step).'],
      check: mc('Which step order is wiser?', ['Send confirmation email first', 'Do compensable steps first; irreversible steps last', 'Random', 'Always email last'], 1, 'Keep the point of no return late.') },
    { title: 'Master', body: ['Reliability needs a durable saga log (state machine persisted after each step) and the **transactional outbox** so state changes and the events/commands that drive the next step are atomic. Handle timeouts, duplicate commands, out-of-order events, and compensation failures (retry forever, then alert a human). Tools: Temporal/Cadence, AWS Step Functions, Camunda, Axon. Alternatives that avoid the problem: put things that must be consistent into **one service/database** (redraw boundaries), use a database that spans shards with transactions (Spanner, CockroachDB), or accept eventual consistency with reconciliation jobs. Rule: **avoid distributed transactions by design when you can**.'],
      check: mc('What is often the best way to avoid distributed transactions?', ['Add more services', 'Keep data that must change together inside one service/database', 'Use a bigger cache', 'Disable retries'], 1, 'Redraw boundaries.') },
  ],
  diagram: { caption: 'Order saga with compensation', rows: [['Orders: create PENDING'], ['Inventory: reserve'], ['Payments: charge'], ['Orders: COMPLETED  (on failure: compensate backwards)']], link: 'chain' },
  sections: { when: ['2PC: within a trusted system with XA-capable databases and low contention. Sagas: business processes across services.'], whenNot: ['Do not reach for sagas if one database can own the data; do not use 2PC across the public internet or many services.'], tradeoffs: ['Strong atomicity vs availability; sagas trade isolation for scalability.'], real: ['Uber and Airbnb use workflow engines (Cadence/Temporal); banks use 2PC internally; Amazon order pipelines are saga-like.'] },
  connects: 'Sagas combine queues (reliable messaging), idempotency (safe retries) and eventual consistency (CAP) from the earlier lessons.',
  quiz: [
    mc('Which style has a central coordinator telling services what to do?', ['Choreography', 'Orchestration', 'Sharding', 'Caching'], 1, 'Orchestrator drives the flow.'),
    mc('2PC phase 1 is called…?', ['Commit', 'Prepare/vote', 'Rollback', 'Heartbeat'], 1, 'Participants vote on readiness.'),
    mc('What do sagas give up compared with ACID transactions?', ['Availability', 'Isolation: intermediate states are visible', 'Speed', 'Retries'], 1, 'Others may observe in-progress state.'),
    mc('The refund call in your saga times out. What should the orchestrator do?', ['Give up silently', 'Retry with the same idempotency key until it succeeds, then alert if stuck', 'Delete the order', 'Charge again'], 1, 'Compensations must be reliable and idempotent.', 'scenario'),
    mc('Can "send SMS" be compensated?', ['Yes, unsend it', 'No: place it as the last step or send a correction', 'Yes with 2PC', 'Only with Redis'], 1, 'Irreversible side effects go at the end.', 'scenario'),
  ],
  interview: { q: 'How would you maintain consistency for an order that spans payment, inventory and shipping services?', model: 'Avoid a distributed transaction if possible by choosing service boundaries carefully. Otherwise use a saga: local transactions with compensations (release stock, refund), orchestrated or choreographed, with a persisted state machine, transactional outbox for reliable messaging, idempotent steps and retries, irreversible steps last, and visible intermediate states (PENDING). Contrast with 2PC: strong atomicity but blocking, coordinator failure and poor availability. Add monitoring and manual intervention for stuck sagas.', points: [pt('Considers avoiding the problem via boundaries', 'boundar', 'one service', 'avoid'), pt('Saga with compensations', 'saga', 'compensat'), pt('Orchestration vs choreography', 'orchestrat', 'choreograph'), pt('Idempotent steps/outbox/state machine', 'idempot', 'outbox', 'state machine', 'persist'), pt('2PC drawbacks', '2pc', 'two-phase', 'block')] },
  challenge: { q: 'Write the saga for "book a trip": flight + hotel + payment. List steps, compensations, and what the user sees if payment fails after both bookings are held.', hints: ['What is the compensation for a held booking?', 'Which step is hardest to undo?'], model: 'Steps: hold flight (comp: release hold) → hold hotel (comp: release) → charge payment (comp: refund) → confirm both. If payment fails: release hotel, release flight, mark trip FAILED, tell the user. User sees "pending" while holds exist. Holds expire (TTL) as a safety net if the orchestrator dies.', points: [pt('Ordered steps with compensations', 'release', 'refund', 'compensat'), pt('Failure path cancels earlier holds', 'release', 'cancel'), pt('Pending state visible to user', 'pending'), pt('Expiry/TTL safety net', 'expire', 'ttl', 'timeout')] },
  summary: { key: ['No cross-service ACID; use 2PC or sagas.', 'Saga = local transactions + compensations.', 'Idempotency and durable state make sagas reliable.'], mistakes: ['Choosing microservices then needing cross-service transactions everywhere.', 'Compensations that are not idempotent.'], remember: 'Prefer designs that need no distributed transaction.' },
  refs: [ref('microservices.io: Saga pattern', 'https://microservices.io/patterns/data/saga.html', 'Clear description of orchestration and choreography.'), ref('Temporal: What is a saga?', 'https://temporal.io/blog/compensating-actions-part-of-a-complete-breakfast-with-sagas', 'Practical walk-through of compensations.'), ref('Garcia-Molina & Salem: Sagas (1987)', 'https://www.cs.cornell.edu/andru/cs711/2002fa/reading/sagas.pdf', 'The original paper, short and readable.')],
},
{
  id: 'consensus-locks', title: 'Consensus, leader election and distributed locks', stage: 4, tier: 'advanced', minutes: 50, prereq: ['cap-consistency', 'replication-sharding'], related: ['dist-transactions'],
  hook: { story: 'Three database nodes must agree on who is the primary. The primary crashes. Two of the remaining nodes each decide, independently, "I am the new primary".', ask: 'What disasters follow when two nodes both accept writes? How can nodes that can only exchange unreliable messages still agree on a single answer?', hints: ['Think of voting: how many votes make a decision unambiguous?', 'Could two groups both hold a majority?', 'What should the old primary do if it comes back?'], reveal: 'Both nodes accept different writes (**split brain**) and data diverges irrecoverably. Systems use **consensus** protocols (Raft, Paxos) built on **majority quorums**: any two majorities overlap, so two conflicting decisions cannot both be approved.' },
  levels: [
    { title: 'Understand', body: ['**Consensus** is getting several machines to agree on a single value (who is leader, what is the next log entry), even though machines can crash and messages can be lost.', 'The trick is **majority voting**: with 5 nodes, a decision needs 3. Two different groups of 3 must share at least one node, so conflicting decisions are impossible.', '**Leader election** picks one node to coordinate (accept writes). **Distributed locks** make sure only one worker does a job at a time.'],
      check: mc('With 5 nodes, how many votes are a majority?', ['2', '3', '4', '5'], 1, 'floor(5/2)+1 = 3.') },
    { title: 'Explore', body: ['**Raft** in brief: nodes are followers, candidates or a leader. Followers that miss the leader\'s heartbeat start an election with a higher **term** number; a candidate needs a majority of votes. The leader appends writes to its log and commits an entry once a majority has stored it. A cluster of 2f+1 nodes tolerates f failures (3 nodes: 1 failure; 5 nodes: 2).', 'Used inside etcd (Kubernetes), Consul, CockroachDB, and the ZooKeeper-like family (ZAB). Applications rarely implement it; they **use** these systems for coordination and metadata.'],
      steps: ['**Why odd cluster sizes:** 4 nodes tolerate the same 1 failure as 3 but need 3 votes: no gain.', '**Fencing tokens:** every lock grant carries an increasing number; storage rejects writes with an older token, protecting against a paused ex-leader.', '**Leases:** a lock/leadership expires after a time unless renewed.', '**Redis locks:** simple (`SET key val NX PX 30000`) but not safe for correctness under failures; fine for efficiency (avoid duplicate work).'],
      check: mc('A 5-node Raft cluster can tolerate how many node failures?', ['1', '2', '3', '5'], 1, 'f = (5-1)/2 = 2.') },
    { title: 'Apply', body: ['**Scenario: two workers both run the nightly invoice job.** Use a lock with a lease. But worker A pauses for 40 s (garbage collection) while holding a 30 s lease; B gets the lock; A wakes up and still thinks it holds it: both write. Defence: a **fencing token** checked by the database (`WHERE token >= last_token`) or make the job idempotent so double execution is harmless.', 'Guidance: use a coordination service (etcd/ZooKeeper) for correctness-critical leadership; use a database row with a unique constraint or advisory lock for simple cases; and prefer idempotency over locks wherever possible.'],
      check: mc('A paused worker wakes after its lock lease expired. What protects data?', ['Nothing', 'A fencing token validated by the resource', 'A bigger lease only', 'More workers'], 1, 'The storage rejects stale holders.') },
    { title: 'Master', body: ['Limits: **FLP impossibility** says no deterministic protocol can guarantee consensus in a fully asynchronous system with even one crash; practical protocols rely on timeouts (partial synchrony) and sacrifice liveness (not safety) during bad periods. Consensus costs latency: every commit needs a majority round trip, so cross-region consensus adds tens to hundreds of ms. Design patterns: keep the consensus group small and metadata-only (cluster membership, leader, config), and run the bulk data path on top; multi-Raft shards data across many small Raft groups (CockroachDB, TiKV). Byzantine fault tolerance (blockchains) is a different, costlier problem.'],
      check: mc('Why keep consensus groups small and for metadata?', ['They are cheaper to name', 'Each decision needs a majority round trip, so throughput and latency are limited', 'Encryption', 'DNS'], 1, 'Coordination is the expensive part.') },
  ],
  diagram: { caption: 'Majority vote elects one leader', rows: [['Node 1 (old leader, down)'], ['Node 2 (candidate)', 'Node 3', 'Node 4', 'Node 5'], ['Node 2 gets 3 of 5 votes: leader']], link: 'chain' },
  sections: { when: ['Leader election, cluster membership, configuration, critical locks, replicated logs.'], whenNot: ['Do not build your own consensus; do not use it on the hot data path unless necessary.'], tradeoffs: ['Safety and single agreement vs latency, throughput and operational cost.'], real: ['etcd (Kubernetes), Consul, ZooKeeper (Kafka historically), Google Chubby/Spanner (Paxos).'] },
  connects: 'Consensus is the machinery behind the CP side of CAP and behind reliable failover from the replication lesson.',
  quiz: [
    mc('Why do two majorities always overlap?', ['By luck', 'Two sets each larger than half must share at least one member', 'DNS', 'Replication lag'], 1, 'Pigeonhole.'),
    mc('What is split brain?', ['A bug in the UI', 'Two nodes both acting as primary', 'A slow query', 'Cache miss'], 1, 'Diverging writes.'),
    mc('What is a fencing token for?', ['Encryption', 'Rejecting writes from a stale lock holder', 'Caching', 'Routing'], 1, 'Monotonic number checked by the resource.'),
    mc('You need a lock so two cron instances do not both run a job that is already idempotent. Simplest safe option?', ['Raft cluster', 'A DB advisory lock or just rely on idempotency', 'Kafka', 'CDN'], 1, 'Do not over-engineer.', 'scenario'),
    mc('A 3-node cluster loses 2 nodes. What happens to writes?', ['Continue', 'Blocked: no majority available (CP behaviour)', 'Doubled', 'Cached'], 1, 'Safety over availability.', 'scenario'),
  ],
  interview: { q: 'How do distributed systems elect a leader and avoid split brain?', model: 'They use a consensus protocol such as Raft or Paxos. Nodes vote; a candidate needs a majority, so two leaders cannot be elected for the same term because majorities overlap. Leaders send heartbeats; followers time out and start elections with a higher term. Old leaders step down when they see a higher term, and writes commit only after replicating to a majority. Locks/leases carry fencing tokens to protect against stale holders. Cluster sizes are odd (3 or 5); costs are write latency and unavailability without a quorum.', points: [pt('Majority quorum voting', 'majority', 'quorum'), pt('Terms/heartbeats/timeouts (Raft)', 'term', 'heartbeat', 'timeout', 'raft'), pt('Overlap prevents two leaders', 'overlap', 'two leaders', 'split brain'), pt('Fencing tokens / leases', 'fenc', 'lease'), pt('Costs: latency, needs quorum', 'latency', 'unavailab', 'no quorum')] },
  challenge: { q: 'You run a 3-node etcd cluster across 3 zones. A whole zone goes offline. What still works? What if a second zone also goes offline? What would you change for a region-wide design?', hints: ['Count majorities.', 'Which operations need a quorum?'], model: 'With 1 zone lost, 2 of 3 nodes remain: majority, so reads/writes continue. With 2 zones lost, 1 of 3 remains: no quorum; writes stop (and linearizable reads), preserving safety. For regional resilience run 5 nodes across 3+ zones/regions (tolerates 2) accepting higher write latency, or use per-region clusters with asynchronous replication.', points: [pt('Correct majority arithmetic', '2 of 3', 'majority', 'quorum'), pt('Second failure halts writes', 'stop', 'unavailable', 'no quorum'), pt('Proposes 5 nodes / geo design trade-off', '5', 'latency', 'region')] },
  summary: { key: ['Consensus = agree despite failures, using majorities.', 'Raft: terms, heartbeats, majority commit.', 'Use fencing tokens; prefer idempotency to locks.'], mistakes: ['Even-sized clusters.', 'Redis lock for strict correctness.'], remember: 'Coordination is expensive: use it sparingly and let a proven system do it.' },
  refs: [ref('The Raft visualization', 'https://raft.github.io/', 'Interactive explanation of leader election and log replication.'), ref('Martin Kleppmann: How to do distributed locking', 'https://martin.kleppmann.com/2016/02/08/how-to-do-distributed-locking.html', 'The definitive argument for fencing tokens.'), ref('etcd documentation: Why etcd', 'https://etcd.io/docs/latest/', 'Production consensus store used by Kubernetes.')],
},
{
  id: 'event-driven-obs', title: 'Event-driven design, service discovery and observability', stage: 4, tier: 'should', minutes: 50, prereq: ['queues', 'backend-servers', 'distributed-intro'], related: ['idempotency-retries'],
  hook: { story: 'You have 40 services, each with many changing instances. A user reports "checkout is slow". The request passed through 9 services.', ask: 'How does service A find an instance of service B when instances come and go? How do you work out which of the 9 hops was slow?', hints: ['Hard-coding IP addresses breaks as soon as an instance restarts.', 'You need one trace of the entire request across all services.', 'Logs on 40 machines are useless unless they are collected and correlated.'], reveal: 'Services register themselves in a **service registry** (or the platform provides DNS-based discovery) so callers look up healthy instances. **Observability** (logs, metrics, traces linked by a request id) lets you see inside the system and follow one request across all services.' },
  levels: [
    { title: 'Understand', body: ['**Event-driven architecture:** instead of service A calling B directly ("send the invoice!"), A publishes a fact ("OrderPlaced") and any interested services react. A does not know or wait for them.', '**Service discovery:** a directory of "where is the payments service right now?" because instances start, stop and move.', '**Observability:** the ability to ask new questions about a running system from the data it emits. Three pillars: **logs** (what happened), **metrics** (numbers over time), **traces** (the path of one request).'],
      check: mc('In an event-driven design, who decides which services react to OrderPlaced?', ['The publisher', 'Subscribers choose to listen', 'The user', 'DNS'], 1, 'Publishers are decoupled from consumers.') },
    { title: 'Explore', body: ['**Events vs commands:** an event is a past-tense fact (OrderPlaced), a command asks for an action (ChargeCard). **Pub/sub** fans events to many consumers; **event sourcing** stores every event as the source of truth; **CQRS** separates the write model from read-optimised views built from events.', '**Discovery:** *client-side* (the caller queries a registry like Consul/Eureka and picks an instance) or *server-side* (a load balancer/service mesh/Kubernetes Service does the lookup). Registrations use heartbeats and TTL to drop dead instances.'],
      steps: ['**Metrics:** RED (Rate, Errors, Duration) for services; USE (Utilisation, Saturation, Errors) for resources. Histograms for percentiles. (Prometheus, Grafana)', '**Logs:** structured JSON with a `trace_id`; centralised (ELK, Loki).', '**Traces:** a trace is a tree of spans, one per hop with timings (OpenTelemetry, Jaeger).', '**Alerts** on symptoms users feel (error rate, latency SLO burn), not on every cause.'],
      check: mc('What links logs from different services for one user request?', ['A shared trace/correlation id', 'The date', 'The IP', 'Nothing'], 0, 'Propagate an id through every call.') },
    { title: 'Apply', body: ['**Scenario: checkout got slow after yesterday\'s release.** Dashboard (metrics) shows p99 up on checkout; a trace shows 2.4 s inside the Inventory service on a call to a new endpoint; its logs for that trace id reveal a query without an index. Metrics told you *that*, traces told you *where*, logs told you *why*. Without all three you would guess.', 'Event-driven trade-off scenario: the "welcome email" and "analytics" reactions are independent of sign-up speed, so they become subscribers. But "did the sign-up finish?" now needs tracing events, and a poison event can block a consumer.'],
      check: mc('Metrics show that checkout is slow. What gives the *where* across services?', ['More metrics only', 'Distributed traces', 'DNS', 'CDN'], 1, 'Spans show time per hop.') },
    { title: 'Master', body: ['Event-driven pitfalls: hidden coupling through event schemas (use versioning and a schema registry), ordering and duplicate delivery, eventual consistency for read models, debugging flows with no central code path, and event storms. Prefer events for notifications and integration, commands/RPC where the caller needs the result. Observability at scale: **sampling** traces (head or tail-based), cardinality control on metrics (never label by user id), SLO-based alerting with burn rates, and keeping observability itself off the critical path. A **service mesh** (Istio/Linkerd) moves discovery, retries, mTLS and telemetry into sidecars.'],
      check: mc('Why avoid putting user_id as a metric label?', ['Privacy only', 'High cardinality explodes storage and cost', 'Metrics must be text', 'It breaks DNS'], 1, 'Millions of time series are unaffordable.') },
  ],
  diagram: { caption: 'Publish once, many react', rows: [['Orders service'], ['Event bus (OrderPlaced)'], ['Email', 'Inventory', 'Analytics']], link: 'fan' },
  sections: { when: ['Events: fan-out, decoupling, audit trails, async integration. Observability: always, from day one for anything distributed.'], whenNot: ['Do not make everything event-driven; avoid events when the caller needs an immediate answer.'], tradeoffs: ['Decoupling and extensibility vs harder tracing and eventual consistency.'], real: ['Netflix and Uber trace requests across hundreds of services; Kafka-based event platforms at LinkedIn; Kubernetes DNS discovery.'] },
  connects: 'Events ride on queues; discovery and observability are what keep a large microservice estate understandable.',
  quiz: [
    mc('Which is a trace?', ['A single log line', 'The path and timings of one request across services', 'A CPU number', 'A DNS record'], 1, 'A tree of spans.'),
    mc('What does service discovery solve?', ['Finding current instances of a service', 'Password storage', 'Index design', 'Image compression'], 0, 'Instances are dynamic.'),
    mc('RED metrics stand for?', ['Rate, Errors, Duration', 'Read, Edit, Delete', 'Redis, ETL, DNS', 'Retry, Ensure, Deploy'], 0, 'Core service health metrics.'),
    mc('A new subscriber must process OrderPlaced events from last week too. Which design supports it?', ['Fire-and-forget pub/sub only', 'A durable log with replay (Kafka)', 'DNS', 'Cache'], 1, 'Replay needs retained events.', 'scenario'),
    mc('You alert whenever any pod\'s CPU > 80%. Result?', ['Perfect', 'Noisy, cause-based alerts; prefer alerts on user-facing symptoms/SLOs', 'No alerts', 'Cheaper'], 1, 'Alert on impact.', 'scenario'),
  ],
  interview: { q: 'How would you debug a slow request in a system of 30 microservices?', model: 'Start from metrics/SLO dashboards to confirm scope (which endpoint, which percentile, since when, correlating with deploys). Pull a distributed trace for a slow request to find the slowest span/hop. Use logs filtered by the trace id for details in that service, and resource metrics (USE) for saturation. Form a hypothesis (slow query, retry storm, downstream timeout), verify, fix and add alerts/tests. Mention correlation ids, structured logs and OpenTelemetry.', points: [pt('Metrics to scope the problem', 'metric', 'dashboard', 'slo'), pt('Distributed tracing for the slow hop', 'trace', 'span'), pt('Logs by correlation/trace id', 'log', 'correlation', 'trace id'), pt('Resource saturation / hypotheses', 'saturation', 'cpu', 'query', 'hypothes'), pt('Alerts/follow-up', 'alert', 'fix')] },
  challenge: { q: 'Design the event flow for "user signs up": what events exist, who subscribes, and what do you do if the email service is down for an hour?', hints: ['Is sign-up success dependent on the email?', 'Where do events wait?'], model: 'Sign-up writes the user and publishes UserRegistered (outbox). Subscribers: Email (welcome), Analytics, CRM, Referral. Events sit in a durable broker; the email consumer retries with backoff and processes the backlog when it returns; sign-up never blocked. Consumers are idempotent (dedupe by event id); a DLQ catches poison events.', points: [pt('UserRegistered event with several subscribers', 'subscrib', 'userregistered', 'event'), pt('Durable broker buffers during outage', 'durable', 'broker', 'queue', 'backlog'), pt('Idempotent consumers / DLQ', 'idempot', 'dedupe', 'dlq', 'dead')] },
  summary: { key: ['Events = facts others react to.', 'Registry/DNS finds live instances.', 'Logs + metrics + traces = observability.'], mistakes: ['Event spaghetti with no schemas.', 'No trace ids.'], remember: 'If you cannot see it, you cannot operate it.' },
  refs: [ref('OpenTelemetry: Observability primer', 'https://opentelemetry.io/docs/concepts/observability-primer/', 'Official, vendor-neutral explanation of logs, metrics and traces.'), ref('Martin Fowler: What do you mean by "Event-Driven"?', 'https://martinfowler.com/articles/201701-event-driven.html', 'Untangles the four meanings of event-driven.'), ref('Google SRE Book: Monitoring', 'https://sre.google/sre-book/monitoring-distributed-systems/', 'Symptom-based alerting and golden signals.')],
},
]
